package android.net;import java.util.Objects;public final class Uri {private final String value;private Uri(String value){this.value=value;}public static Uri parse(String value){return new Uri(value);}@Override public boolean equals(Object other){return other instanceof Uri uri&&value.equals(uri.value);}@Override public int hashCode(){return Objects.hash(value);}@Override public String toString(){return value;}}
